257	    /// Whether `incoming` is the protocol's "a new message has started" signal for `stream`.
258	    ///
259	    /// It requires **two present ids that differ**. An ABSENT id is never a boundary, in either
260	    /// direction:
261	    ///
262	    /// - ACP allows an agent to stream a whole message untagged, so absence carries no
263	    ///   message-identity information to compare against.
264	    /// - `ContentChunk::message_id` is deserialised `DefaultOnError`, so ONE malformed id on the
265	    ///   wire arrives as `None`. Treating that as a boundary would split one message in two and
266	    ///   insert a [`MESSAGE_JOIN`] newline into [`Self::completed_text`] — and that text is the
267	    ///   activity's replay-authoritative result. A fabricated newline in the result is a
268	    ///   correctness bug, so the boundary rule refuses to infer one from a missing value.
269	    fn starts_a_new_message(&self, stream: ChunkStream, incoming: Option<&MessageId>) -> bool {
270	        let open = self.slot(stream).and_then(|open| open.id.as_ref());
271	        match (open, incoming) {
272	            (Some(open), Some(incoming)) => open != incoming,
273	            _ => false,
274	        }
275	    }
276	
277	    /// Closes `stream`'s open message, emitting its durable [`ActivityEventKind::Message`] and — for
278	    /// the answer stream only — folding its text into [`Self::completed_text`].
279	    fn close(&mut self, stream: ChunkStream) -> Vec<EventKind> {
280	        let Some(open) = self.slot_mut(stream).take() else {
281	            return Vec::new();
282	        };
283	        if open.text.is_empty() {
284	            return Vec::new();
285	        }
286	        if stream.feeds_the_result() {
287	            if !self.completed.is_empty() {
288	                self.completed.push_str(MESSAGE_JOIN);
289	            }
290	            self.completed.push_str(&open.text);
291	        }
292	        vec![(
293	            ActivityEventKind::Message {
294	                role: stream.role(),
295	                text: open.text,
296	            },
297	            false,
298	        )]
299	    }
