301	    /// The message `stream` is currently accumulating, if any.
302	    const fn slot(&self, stream: ChunkStream) -> Option<&OpenMessage> {
303	        match stream {
304	            ChunkStream::AgentMessage => self.agent_message.as_ref(),
305	            ChunkStream::AgentThought => self.agent_thought.as_ref(),
306	            ChunkStream::User => self.user.as_ref(),
307	        }
308	    }
309	
310	    /// The buffer slot `stream` accumulates into, mutably.
311	    const fn slot_mut(&mut self, stream: ChunkStream) -> &mut Option<OpenMessage> {
312	        match stream {
313	            ChunkStream::AgentMessage => &mut self.agent_message,
314	            ChunkStream::AgentThought => &mut self.agent_thought,
315	            ChunkStream::User => &mut self.user,
316	        }
317	    }
318	}
