323	/// as not-text and reaches the transcript verbatim rather than being mistaken for text.
324	fn block_text(block: &ContentBlock) -> Option<&str> {
325	    match block {
326	        ContentBlock::Text(text) => Some(&text.text),
327	        _ => None,
328	    }
