270	///
271	/// A Response with any other id answers a request this adapter never sent.
272	fn handle_response<R, W>(
273	    context: &PumpContext<R, W>,
274	    state: &mut PumpState,
275	    response: JsonRpcResponse,
276	) {
277	    if response.id != context.prompt_id {
278	        tracing::warn!(
279	            received = ?response.id,
280	            expected = ?context.prompt_id,
281	            "acp adapter: response for an id this client never requested; ignoring the frame"
282	        );
283	        return;
284	    }
285	    let Some(outcome_tx) = state.outcome_tx.take() else {
286	        tracing::warn!(
287	            id = ?response.id,
288	            "acp adapter: a second response for the prompt id; ignoring the frame"
289	        );
290	        return;
291	    };
292	    let flushed = state.accumulator.finish();
293	    emit(context, state, flushed);
294	    // Every other frame gets a verbatim twin, and this one decides the activity's result.
295	    emit(
296	        context,
297	        state,
298	        vec![translate::prompt_response_kind(&response)],
299	    );
300	    emit(context, state, vec![stop_event_kind(&response)]);
301	    let outcome = PromptOutcome {
302	        response,
303	        text: state.accumulator.completed_text().to_owned(),
304	    };
305	    // A dropped receiver means the caller abandoned `wait_result`; not an error worth surfacing.
306	    let _ = outcome_tx.send(PumpEnd::Answered(Box::new(outcome)));
307	    state.event_tx = None;
308	}
