311	///
312	/// **Always emitted.** A transcript that just stops mid-stream with no terminal boundary is not an
313	/// honest record of a failed turn, and there is nothing to invent: `aion_core`'s
314	/// [`StopKind::Error`] exists for exactly the case where a run stopped because of an error. The
315	/// three non-success shapes each get one carrying the reason, and the frame itself is on the
316	/// transcript verbatim beside it ([`translate::prompt_response_kind`]).
317	///
318	/// `error` is checked before `result` so the boundary agrees with the terminal interpretation in
319	/// [`crate::outcome`], which reports an error Response as the failure it is regardless of what else
320	/// the frame carries.
321	fn stop_event_kind(response: &JsonRpcResponse) -> EventKind {
322	    let reason = if let Some(error) = response.error.as_ref() {
323	        StopKind::Error {
324	            message: format!(
325	                "session/prompt failed (code {}): {}",
326	                error.code, error.message
327	            ),
328	        }
329	    } else if let Some(result) = response.result.as_ref() {
330	        match serde_json::from_value::<PromptResponse>(result.clone()) {
331	            Ok(prompt) => translate::stop_kind(prompt.stop_reason),
332	            Err(source) => {
333	                tracing::warn!(%source, "acp adapter: undecodable session/prompt result");
334	                StopKind::Error {
335	                    message: format!(
336	                        "the session/prompt result is not an ACP PromptResponse ({source}): {result}"
337	                    ),
338	                }
339	            }

490	        assert_eq!(accumulator.completed_text(), "ab");
491	    }
