500	/// Residual honesty: a child that never reads its stdin AT ALL cannot be written to by anyone — the
501	/// pipe is full, mutex or no mutex — so `intervene` can still block on such an agent. That is a
502	/// property of the pipe rather than of this adapter's locking, and the read loop no longer stalls
503	/// with it, so the turn's terminal result still arrives.
504	fn queue_response<R, W>(
505	    context: &PumpContext<R, W>,
506	    state: &mut PumpState,
507	    response: JsonRpcResponse,
508	) where
509	    R: AsyncRead + Unpin + Send + 'static,
510	    W: AsyncWrite + Unpin + Send + 'static,
511	{
512	    // Reap finished writers, so the set holds only writes genuinely still in flight (bounded by the
513	    // agent's own outstanding-request count) rather than growing for the life of the turn.
514	    while let Some(joined) = state.writers.try_join_next() {
515	        if let Err(error) = joined {
516	            tracing::error!(%error, "acp adapter: a peer-request answer task did not complete");
517	        }
518	    }
519	    let connection = Arc::clone(&context.connection);
520	    state.writers.spawn(async move {
521	        // A failed write means the agent's stdin is gone: the run is over and the pump's next `recv`
522	        // will end the loop. It is logged rather than propagated because the pump has no error
523	        // channel — and it must not be silent.
524	        if let Err(error) = connection.send_response(&response).await {
525	            tracing::warn!(%error, "acp adapter: could not answer a peer request");
526	        }
527	    });
528	}
