530	/// Stamps and forwards translated kinds, advancing the worker sequence.
531	///
532	/// A send failure means the consumer dropped the events stream; the pump keeps going so the terminal
533	/// result and the peer-request answers still happen. That is not an error.
534	///
535	/// Once the transcript sender has been dropped at the terminal Response, a later frame has nowhere
536	/// durable to go. It is logged at `warn` with its translated kind rather than discarded quietly: a
537	/// frame arriving after the turn's answer is an agent-conformance problem, and silence about it
538	/// would leave an operator with no trace of it at all.
539	fn emit<R, W>(context: &PumpContext<R, W>, state: &mut PumpState, kinds: Vec<EventKind>) {
540	    for kind in kinds {
541	        let event = context.identity.stamp(state.worker_seq, kind);
542	        state.worker_seq = state.worker_seq.saturating_add(1);
543	        if let Some(sender) = state.event_tx.as_ref() {
544	            let _ = sender.send(event);
545	        } else {
546	            tracing::warn!(
547	                kind = ?event.kind,
548	                "acp adapter: a frame arrived after the terminal session/prompt response; the \
549	                 transcript stream is already closed"
550	            );
551	        }
552	    }
553	}

