1	//! Non-blocking peer-response writes and transcript event emission.
2	
3	use super::*;
4	
5	/// Queues one response for writing on a task of its own, and reaps the finished writers.
6	///
7	/// **The write must not be awaited in the read loop.** The shared transport holds the connection's
8	/// writer mutex across `write_all` + `flush`, so a child whose stdin buffer is full blocks that write
9	/// until it reads — and it cannot read while this loop has stopped draining its stdout. Awaiting
10	/// inline is therefore a real deadlock with no timeout (observed at 729 answered permission requests
11	/// against an agent that did not read its stdin), and one that `intervene` could not rescue, because
12	/// cancelling needs the same mutex. Writing off the loop keeps stdout draining, which is what lets
13	/// the child make progress at all.
14	///
15	/// The "exactly one answer per peer request, never two, never a mismatched id" property is
16	/// untouched: the response is built from that request's own id before it is queued, and it is queued
17	/// once. Only WHEN the bytes leave changes — never how many, nor under which id. Two answers may
18	/// leave in a different order than their requests arrived, which JSON-RPC allows (responses are
19	/// id-correlated, not positional), and the transport's writer mutex still makes each frame atomic.
20	///
21	/// Residual honesty: a child that never reads its stdin AT ALL cannot be written to by anyone — the
22	/// pipe is full, mutex or no mutex — so `intervene` can still block on such an agent. That is a
23	/// property of the pipe rather than of this adapter's locking, and the read loop no longer stalls
24	/// with it, so the turn's terminal result still arrives.
25	pub(super) fn queue_response<R, W>(
26	    context: &PumpContext<R, W>,
27	    state: &mut PumpState,
28	    response: JsonRpcResponse,
29	) where
30	    R: AsyncRead + Unpin + Send + 'static,
31	    W: AsyncWrite + Unpin + Send + 'static,
32	{
33	    // Reap finished writers, so the set holds only writes genuinely still in flight (bounded by the
34	    // agent's own outstanding-request count) rather than growing for the life of the turn.
35	    while let Some(joined) = state.writers.try_join_next() {
36	        if let Err(error) = joined {
37	            tracing::error!(%error, "acp adapter: a peer-request answer task did not complete");
38	        }
39	    }
40	    let connection = Arc::clone(&context.connection);
41	    state.writers.spawn(async move {
42	        // A failed write means the agent's stdin is gone: the run is over and the pump's next `recv`
43	        // will end the loop. It is logged rather than propagated because the pump has no error
44	        // channel — and it must not be silent.
45	        if let Err(error) = connection.send_response(&response).await {
46	            tracing::warn!(%error, "acp adapter: could not answer a peer request");
47	        }
48	    });
49	}
50	
51	/// Stamps and forwards translated kinds, advancing the worker sequence.
52	///
53	/// A send failure means the consumer dropped the events stream; the pump keeps going so the terminal
54	/// result and the peer-request answers still happen. That is not an error.
55	///
56	/// Once the transcript sender has been dropped at the terminal Response, a later frame has nowhere
57	/// durable to go. It is logged at `warn` with its translated kind rather than discarded quietly: a
58	/// frame arriving after the turn's answer is an agent-conformance problem, and silence about it
59	/// would leave an operator with no trace of it at all.
60	pub(super) fn emit<R, W>(
61	    context: &PumpContext<R, W>,
62	    state: &mut PumpState,
63	    kinds: Vec<EventKind>,
64	) {
65	    for kind in kinds {
66	        let event = context.identity.stamp(state.worker_seq, kind);
67	        state.worker_seq = state.worker_seq.saturating_add(1);
68	        if let Some(sender) = state.event_tx.as_ref() {
69	            let _ = sender.send(event);
70	        } else {
71	            tracing::warn!(
72	                kind = ?event.kind,
73	                "acp adapter: a frame arrived after the terminal session/prompt response; the \
74	                 transcript stream is already closed"
75	            );
76	        }
77	    }
78	}

